def is_cp(self, atol: float | None = None, rtol: float | None = None) -> bool:
        """Test if Choi-matrix is completely-positive (CP)"""
        if atol is None:
            atol = self.atol
        if rtol is None:
            rtol = self.rtol
        neg_rates = self.rates[self.rates < 0]
        return np.allclose(neg_rates, 0, atol=atol, rtol=rtol)

